    if (D > 0.) {
        float t = -B - sqrtf(D);

        if ((t > 0.0) && (t < isect.t)) {
            isect.t = t;
            isect.hit = 1;
            isect.p = ray.org + t * ray.dir;
            isect.n = isect.p - sphere.center;
            vnormalize(isect.n);
        }
    }
}

static inline void ray_sphere_intersect_precomputed(Isect &isect, const Ray &ray, const Sphere &sphere,
                                                     const vec &relativeOrigin, float originTerm) {
    float B = dot(relativeOrigin, ray.dir);
    float D = B * B - originTerm;

    if (D > 0.) {
        float t = -B - sqrtf(D);

        if ((t > 0.0) && (t < isect.t)) {
            isect.t = t;
            isect.hit = 1;
            isect.p = ray.org + t * ray.dir;
            isect.n = isect.p - sphere.center;
            vnormalize(isect.n);
        }
    }
}

static inline void orthoBasis(vec basis[3], const vec &n) {
    basis[2] = n;
    basis[1].x = 0.0;
    basis[1].y = 0.0;
    basis[1].z = 0.0;

    if ((n.x < 0.6f) && (n.x > -0.6f)) {
        basis[1].x = 1.0;
    } else if ((n.y < 0.6f) && (n.y > -0.6f)) {
        basis[1].y = 1.0;
    } else if ((n.z < 0.6f) && (n.z > -0.6f)) {
        basis[1].z = 1.0;
    } else {
        basis[1].x = 1.0;
    }

    basis[0] = vcross(basis[1], basis[2]);
    vnormalize(basis[0]);

    basis[1] = vcross(basis[2], basis[0]);
    vnormalize(basis[1]);
}

static float ambient_occlusion(Isect &isect, Plane &plane, Sphere spheres[3]) {
    float eps = 0.0001f;
    vec p, n;
    vec basis[3];
    float occlusion = 0.0;

    p = isect.p + eps * isect.n;

    orthoBasis(basis, isect.n);

    vec relativeOrigins[3];
    float originTerms[3];
    for (int snum = 0; snum < 3; ++snum) {
        relativeOrigins[snum] = p - spheres[snum].center;
        originTerms[snum] = dot(relativeOrigins[snum], relativeOrigins[snum]) -
                            spheres[snum].radius * spheres[snum].radius;
    }

    static const int ntheta = NAO_SAMPLES;
    static const int nphi = NAO_SAMPLES;
    static const int ambientRayCount = NAO_SAMPLES * NAO_SAMPLES;
    float directionX[ambientRayCount];
    float directionY[ambientRayCount];
    float directionZ[ambientRayCount];

    // Generate every direction in the original ray order before testing them.
    int rayIndex = 0;
    for (int j = 0; j < ntheta; j++) {
        for (int i = 0; i < nphi; i++) {
            float theta = sqrtf(drand48());
            float phi = 2.0f * M_PI * drand48();
            float x = cosf(phi) * theta;
            float y = sinf(phi) * theta;
            float z = sqrtf(1.0f - theta * theta);

            // local . global
            directionX[rayIndex] = x * basis[0].x + y * basis[1].x + z * basis[2].x;
            directionY[rayIndex] = x * basis[0].y + y * basis[1].y + z * basis[2].y;
            directionZ[rayIndex] = x * basis[0].z + y * basis[1].z + z * basis[2].z;
            ++rayIndex;
        }
    }

    float nearestT[ambientRayCount];
    for (int r = 0; r < ambientRayCount; ++r)
        nearestT[r] = 1.0e+17f;

    // Each loop iteration updates an independent ray lane, exposing the sphere
    // tests to ordinary compiler loop vectorization without requiring ISA code.
    for (int snum = 0; snum < 3; ++snum) {
        const vec &relativeOrigin = relativeOrigins[snum];
        const float originTerm = originTerms[snum];
        for (int r = 0; r < ambientRayCount; ++r) {
            float B = relativeOrigin.x * directionX[r] + relativeOrigin.y * directionY[r] +
                      relativeOrigin.z * directionZ[r];
            float D = B * B - originTerm;

            if (D > 0.) {
                float t = -B - sqrtf(D);
                if ((t > 0.0) && (t < nearestT[r]))
                    nearestT[r] = t;
            }
        }
    }

    for (int r = 0; r < ambientRayCount; ++r) {
        float d = -dot(plane.p, plane.n);
        float v = directionX[r] * plane.n.x + directionY[r] * plane.n.y + directionZ[r] * plane.n.z;

        if (fabsf(v) < 1.0e-17f)
            continue;
        else {
            float t = -(dot(p, plane.n) + d) / v;
            if ((t > 0.0) && (t < nearestT[r]))
                nearestT[r] = t;
        }
    }

    for (int r = 0; r < ambientRayCount; ++r) {
        if (nearestT[r] < 1.0e+17f)
            occlusion += 1.f;
    }

    occlusion = (ntheta * nphi - occlusion) / (float)(ntheta * nphi);
    return occlusion;
}

/* Compute the image for the scanlines from [y0,y1), for an overall image
   of width w and height h.
 */
static void ao_scanlines(int y0, int y1, int w, int h, int nsubsamples, float image[]) {
    static Plane plane = {vec(0.0f, -0.5f, 0.0f), vec(0.f, 1.f, 0.f)};
    static Sphere spheres[3] = {
        {vec(-2.0f, 0.0f, -3.5f), 0.5f}, {vec(-0.5f, 0.0f, -3.0f), 0.5f}, {vec(1.0f, 0.0f, -2.2f), 0.5f}};

    srand48(y0);

    for (int y = y0; y < y1; ++y) {
        for (int x = 0; x < w; ++x) {
            int offset = 3 * (y * w + x);
            for (int u = 0; u < nsubsamples; ++u) {
                for (int v = 0; v < nsubsamples; ++v) {
                    float px = (x + (u / (float)nsubsamples) - (w / 2.0f)) / (w / 2.0f);
                    float py = -(y + (v / (float)nsubsamples) - (h / 2.0f)) / (h / 2.0f);

                    // Scale NDC based on width/height ratio, supporting non-square image output
                    px *= (float)w / (float)h;

                    float ret = 0.f;
                    Ray ray;
                    Isect isect;

                    ray.org = vec(0.f, 0.f, 0.f);

                    ray.dir.x = px;
                    ray.dir.y = py;
                    ray.dir.z = -1.0f;
                    vnormalize(ray.dir);

                    isect.t = 1.0e+17f;
                    isect.hit = 0;

                    for (int snum = 0; snum < 3; ++snum)
                        ray_sphere_intersect(isect, ray, spheres[snum]);
                    ray_plane_intersect(isect, ray, plane);

                    if (isect.hit)
                        ret = ambient_occlusion(isect, plane, spheres);

                    // Update image for AO for this ray
                    image[offset + 0] += ret;
                    image[offset + 1] += ret;
                    image[offset + 2] += ret;
                }
            }
            // Normalize image pixels by number of samples taken per pixel
            image[offset + 0] /= nsubsamples * nsubsamples;
            image[offset + 1] /= nsubsamples * nsubsamples;
            image[offset + 2] /= nsubsamples * nsubsamples;
        }
    }
}

void ao_serial(int w, int h, int nsubsamples, float image[]) { ao_scanlines(0, h, w, h, nsubsamples, image); }

