                occlusion += 1.f;
        }
    }

    occlusion = (ntheta * nphi - occlusion) / (float)(ntheta * nphi);
    return occlusion;
}

static inline void ao_render_pixel(int x, int y, int w, int h, int nsubsamples,
                                   Plane &plane, Sphere spheres[3], float image[],
                                   uint64_t render_seed) {
    const int offset = 3 * (y * w + x);
    const uint64_t pixel_index = static_cast<uint64_t>(y) * static_cast<uint64_t>(w) + static_cast<uint64_t>(x);
    uint64_t rng = mix64(render_seed ^ pixel_index);

    for (int u = 0; u < nsubsamples; ++u) {
        for (int v = 0; v < nsubsamples; ++v) {
            float px = (x + (u / (float)nsubsamples) - (w / 2.0f)) / (w / 2.0f);
            float py = -(y + (v / (float)nsubsamples) - (h / 2.0f)) / (h / 2.0f);

            // Scale NDC based on width/height ratio, supporting non-square image output
            px *= (float)w / (float)h;

            float ret = 0.f;
            Ray ray;
            Isect isect;

            ray.org = vec(0.f, 0.f, 0.f);

            ray.dir.x = px;
            ray.dir.y = py;
            ray.dir.z = -1.0f;
            vnormalize(ray.dir);

            isect.t = 1.0e+17f;
            isect.hit = 0;

            for (int snum = 0; snum < 3; ++snum)
                ray_sphere_intersect(isect, ray, spheres[snum]);
            ray_plane_intersect(isect, ray, plane);

            if (isect.hit)
                ret = ambient_occlusion(isect, plane, spheres, rng);

            // Update image for AO for this ray
            image[offset + 0] += ret;
            image[offset + 1] += ret;
            image[offset + 2] += ret;
        }
    }

    // Normalize image pixels by number of samples taken per pixel
    image[offset + 0] /= nsubsamples * nsubsamples;
    image[offset + 1] /= nsubsamples * nsubsamples;
    image[offset + 2] /= nsubsamples * nsubsamples;
}

static void ao_render(int w, int h, int nsubsamples, float image[], int threads) {
    static Plane plane = {vec(0.0f, -0.5f, 0.0f), vec(0.f, 1.f, 0.f)};
    static Sphere spheres[3] = {
        {vec(-2.0f, 0.0f, -3.5f), 0.5f}, {vec(-0.5f, 0.0f, -3.0f), 0.5f}, {vec(1.0f, 0.0f, -2.2f), 0.5f}};
    const uint64_t render_seed = make_render_seed();

    if (threads <= 1) {
        for (int y = 0; y < h; ++y)
            for (int x = 0; x < w; ++x)
                ao_render_pixel(x, y, w, h, nsubsamples, plane, spheres, image, render_seed);
        return;
    }

#pragma omp parallel for schedule(static) num_threads(threads)
    for (int y = 0; y < h; ++y)
        for (int x = 0; x < w; ++x)
            ao_render_pixel(x, y, w, h, nsubsamples, plane, spheres, image, render_seed);
}

void ao_serial(int w, int h, int nsubsamples, float image[]) {
    ao_render(w, h, nsubsamples, image, 1);
}

#include <cstring>
#include "render_context.h"
extern "C" void run(RenderInput *c, float *image, int *ids, int threads) {
    const size_t pixel_count = static_cast<size_t>(c->width) * static_cast<size_t>(c->height);
    memset(image, 0, pixel_count * 3 * sizeof(float));
    ao_render(c->width, c->height, c->nsubsamples, image, threads);
}

