    image[offset + 2] = pixel_value;
}

static void ao_render(int w, int h, int nsubsamples, uint64_t seed, int threads, float image[]) {
    const int worker_count = threads > 0 ? threads : 1;

    if (worker_count == 1) {
        for (int y = 0; y < h; ++y)
